window.kbPageData["views/entry/k-7d17ec664d9eac22"] = {"key":"entry/k-7d17ec664d9eac22","state":{"route":"entry/k-7d17ec664d9eac22"},"node":{"id":"k-7d17ec664d9eac22","mode":"k","title":"上下班途中交通事故的工伤认定","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["合理时间和路线的通勤中发生非本人主要责任的交通事故可认定工伤","上下班途中交通事故的工伤认定要求职工负非主要责任"],"qs":["江苏 2023 A类 行测#11","江苏 2023 B类 行测#16"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":1,"directorySummary":"职工在合理时间、沿合理路线通勤时，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","review":{"definition":"职工在合理时间、沿合理路线通勤时，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交车回家途中受伤，下班途中发生事故并不当然排除工伤认定，所以A项错误。实际认定还需判断提前半小时回家是否属于合理通勤，并查明事故责任。题干未交代责任划分，选出C项并不等于已经认定方某构成工伤。","references":[],"evidence":"在上下班途中，受到非本人主要责任的交通事故","disposition":"独立词条","basis":"据原题和解析编释。","title":"上下班途中交通事故的工伤认定","related":[],"examFocus":{"江苏 2023 A类 行测#11":"判断提前下班回家途中发生的交通事故能否认定为工伤，要看通勤时间和路线是否合理，并核对事故责任。"}},"readings":[{"origin":"k-7d17ec664d9eac22","title":"上下班途中交通事故的工伤认定","qs":["江苏 2023 B类 行测#16"],"definition":"职工在合理时间、沿合理路线通勤时，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交车回家途中受伤，下班途中发生事故并不当然排除工伤认定，所以A项错误。实际认定还需判断提前半小时回家是否属于合理通勤，并查明事故责任。题干未交代责任划分，选出C项并不等于已经认定方某构成工伤。","evidence":"在上下班途中，受到非本人主要责任的交通事故","doubt":"","references":[]},{"origin":"k-f38f41e2698f2015","title":"上下班途中交通事故的工伤认定","qs":["江苏 2023 A类 行测#11"],"definition":"职工在合理时间内，沿合理路线往返工作地与住所地、经常居住地或单位宿舍，受到非本人主要责任的交通事故伤害，且无法定排除情形的，应当认定为工伤。","explanation":"方某乘公交回家途中受伤，适用上下班途中交通事故的认定条件，因此A项仅凭事故发生在下班途中便否定工伤，判断有误。题干未交代方某的事故责任，选出C项只能说明未请假提前离岗本身不排除认定。","evidence":"在上下班途中，受到非本人主要责任的交通事故","doubt":"","references":[]}]},"questions":{"江苏 2023 A类 行测#11":{"paper":"江苏 2023 A类 行测","n":11,"mod":"常识判断","src":["22304fe4c340e19d7902.pdf",2],"asrc":["be17f9afe070cf13a0fb.pdf",4],"card":"b67e5363067a6c8959c59b20","links":[{"id":"k-7d17ec664d9eac22","role":"解题依据","why":"通勤情形和事故责任仍是判断能否认定工伤的法定条件。"}]},"江苏 2023 B类 行测#16":{"paper":"江苏 2023 B类 行测","n":16,"mod":"常识判断","src":["22262c34d18cd68fbee4.pdf",3],"asrc":["b08f2713d73015eac675.pdf",6],"card":"46c0d47c902fde44cdbb48f7","links":[{"id":"k-7d17ec664d9eac22","role":"解题依据","why":"事故责任和通勤条件是判断交通事故伤害能否认定为工伤的依据。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-7d17ec664d9eac22":[["江苏 2023 A类 行测#11","江苏 2023 B类 行测#16"]]}};
